css:
@custom-variant dark (&:is(.dark *));

:root {
  --radius: 0.5rem;
  --background: #fafbff;
  --foreground: #15151b;
  --card: #ffffff;
  --card-foreground: #15151b;
  --popover: #ffffff;
  --popover-foreground: #15151b;
  --primary: #0072c5;
  --primary-foreground: #ffffff;
  --secondary: #eff0f4;
  --secondary-foreground: #15151b;
  --muted: #eff0f4;
  --muted-foreground: #5d5d64;
  --accent: #eff0f4;
  --accent-foreground: #15151b;
  --destructive: #ce182c;
  --destructive-foreground: #ffffff;
  --border: #e4e4e8;
  --input: #a4a4a8;
  --ring: #188ceb;
  --chart-1: #0072c5;
  --chart-2: #739800;
  --chart-3: #db9400;
  --chart-4: #de4a84;
  --chart-5: #188ceb;
  --sidebar: #ffffff;
  --sidebar-foreground: #15151b;
  --sidebar-primary: #0072c5;
  --sidebar-primary-foreground: #ffffff;
  --sidebar-accent: #eff0f4;
  --sidebar-accent-foreground: #15151b;
  --sidebar-border: #eff0f4;
  --sidebar-ring: #188ceb;
  --subtle: #f6f6fb;
  --foreground-secondary: #414249;
  --placeholder: #7a7a7e;
  --border-subtle: #eff0f4;
  --border-strong: #d4d4d8;
  --primary-hover: #005ea4;
  --primary-subtle: #f1f8ff;
  --brand: #005ea4;
  --success: #006f3d;
  --success-subtle: #e8fdee;
  --success-solid: #00864c;
  --warning: #7d5200;
  --warning-subtle: #fff5e8;
  --warning-solid: #b77b00;
  --info: #005ea4;
  --info-subtle: #f1f8ff;
  --danger: #af001e;
  --danger-subtle: #fff4f3;
  --highlight: #add55b;
  --highlight-foreground: #0a0a10;
  --inverse: #15151b;
  --inverse-foreground: #ffffff;
  --overlay: #0a0a127a;
  --control-off: #a4a4a8;
  --brand-50: #f1f8ff;
  --brand-100: #e0efff;
  --brand-200: #c0deff;
  --brand-300: #95c9ff;
  --brand-400: #51a9ff;
  --brand-500: #188ceb;
  --brand-600: #0072c5;
  --brand-700: #005ea4;
  --brand-800: #00467d;
  --brand-900: #002f56;
  --brand-950: #001a34;
}
.dark {
  --background: #0a0a10;
  --foreground: #f6f6fb;
  --card: #101016;
  --card-foreground: #f6f6fb;
  --popover: #15151b;
  --popover-foreground: #f6f6fb;
  --primary: #0072c5;
  --primary-foreground: #ffffff;
  --secondary: #28282f;
  --secondary-foreground: #f6f6fb;
  --muted: #1d1d24;
  --muted-foreground: #a4a4a8;
  --accent: #1d1d24;
  --accent-foreground: #f6f6fb;
  --destructive: #ce182c;
  --destructive-foreground: #ffffff;
  --border: #28282f;
  --input: #5d5d64;
  --ring: #51a9ff;
  --chart-1: #51a9ff;
  --chart-2: #add55b;
  --chart-3: #f6b758;
  --chart-4: #fb6ca0;
  --chart-5: #51a9ff;
  --sidebar: #101016;
  --sidebar-foreground: #f6f6fb;
  --sidebar-primary: #0072c5;
  --sidebar-primary-foreground: #ffffff;
  --sidebar-accent: #1d1d24;
  --sidebar-accent-foreground: #f6f6fb;
  --sidebar-border: #1d1d24;
  --sidebar-ring: #51a9ff;
  --subtle: #15151b;
  --foreground-secondary: #d4d4d8;
  --placeholder: #7a7a7e;
  --border-subtle: #1d1d24;
  --border-strong: #414249;
  --primary-hover: #005ea4;
  --primary-subtle: #001a34;
  --brand: #95c9ff;
  --success: #40c079;
  --success-subtle: #00200e;
  --success-solid: #40c079;
  --warning: #f6b758;
  --warning-subtle: #251600;
  --warning-solid: #db9400;
  --info: #95c9ff;
  --info-subtle: #001a34;
  --danger: #ff716d;
  --danger-subtle: #380004;
  --highlight: #8bb700;
  --highlight-foreground: #0a0a10;
  --inverse: #f6f6fb;
  --inverse-foreground: #15151b;
  --overlay: #000005ad;
  --control-off: #5d5d64;
  --brand-50: #f1f8ff;
  --brand-100: #e0efff;
  --brand-200: #c0deff;
  --brand-300: #95c9ff;
  --brand-400: #51a9ff;
  --brand-500: #188ceb;
  --brand-600: #0072c5;
  --brand-700: #005ea4;
  --brand-800: #00467d;
  --brand-900: #002f56;
  --brand-950: #001a34;
}
@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --color-chart-1: var(--chart-1);
  --color-chart-2: var(--chart-2);
  --color-chart-3: var(--chart-3);
  --color-chart-4: var(--chart-4);
  --color-chart-5: var(--chart-5);
  --color-sidebar: var(--sidebar);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-ring: var(--sidebar-ring);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-subtle: var(--subtle);
  --color-foreground-secondary: var(--foreground-secondary);
  --color-placeholder: var(--placeholder);
  --color-border-subtle: var(--border-subtle);
  --color-border-strong: var(--border-strong);
  --color-primary-hover: var(--primary-hover);
  --color-primary-subtle: var(--primary-subtle);
  --color-brand: var(--brand);
  --color-success: var(--success);
  --color-success-subtle: var(--success-subtle);
  --color-success-solid: var(--success-solid);
  --color-warning: var(--warning);
  --color-warning-subtle: var(--warning-subtle);
  --color-warning-solid: var(--warning-solid);
  --color-info: var(--info);
  --color-info-subtle: var(--info-subtle);
  --color-danger: var(--danger);
  --color-danger-subtle: var(--danger-subtle);
  --color-highlight: var(--highlight);
  --color-highlight-foreground: var(--highlight-foreground);
  --color-inverse: var(--inverse);
  --color-inverse-foreground: var(--inverse-foreground);
  --color-overlay: var(--overlay);
  --color-control-off: var(--control-off);
  --color-brand-50: var(--brand-50);
  --color-brand-100: var(--brand-100);
  --color-brand-200: var(--brand-200);
  --color-brand-300: var(--brand-300);
  --color-brand-400: var(--brand-400);
  --color-brand-500: var(--brand-500);
  --color-brand-600: var(--brand-600);
  --color-brand-700: var(--brand-700);
  --color-brand-800: var(--brand-800);
  --color-brand-900: var(--brand-900);
  --color-brand-950: var(--brand-950);
  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);
}
@utility rounded-facet-sm {
  border-radius: calc(var(--radius) * 0.75) calc(var(--radius) * 0.25) calc(var(--radius) * 0.75) calc(var(--radius) * 0.75);
}
@utility rounded-facet {
  border-radius: calc(var(--radius) * 1) calc(var(--radius) * 0.25) calc(var(--radius) * 1) calc(var(--radius) * 1);
}
@utility rounded-facet-lg {
  border-radius: calc(var(--radius) * 1.5) calc(var(--radius) * 0.5) calc(var(--radius) * 1.5) calc(var(--radius) * 1.5);
}
@utility rounded-facet-xl {
  border-radius: calc(var(--radius) * 2) calc(var(--radius) * 0.75) calc(var(--radius) * 2) calc(var(--radius) * 2);
}
@utility rounded-facet-2xl {
  border-radius: calc(var(--radius) * 3) calc(var(--radius) * 1) calc(var(--radius) * 3) calc(var(--radius) * 3);
}
@keyframes facet-shimmer {
  0% { background-position: 200% 0; }
  100% { background-position: -200% 0; }
}
@keyframes facet-marquee {
  from { transform: translateX(0); }
  to { transform: translateX(calc(-50% - var(--gap, 1rem) / 2)); }
}
@keyframes facet-caret-blink {
  0%,70%,100% { opacity: 1; }
  20%,50% { opacity: 0; }
}

@layer base {
  * { border-color: var(--border); outline-color: color-mix(in oklab, var(--ring) 50%, transparent); }
  body { background-color: var(--background); color: var(--foreground); }
}
